/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
program=[]
for raw in Path('prog.pw9').read_text().splitlines():
    line=raw.split(';',1)[0].strip()
    if line: program.append(line.split())
regs={r:0 for r in 'abcd'}
def val(x): return regs[x] if x in regs else int(x)
ip=steps=total=0
outs=[]
while 0 <= ip < len(program):
    ins=program[ip]; op=ins[0]; steps+=1; nxt=ip+1
    if op=='set': regs[ins[1]]=val(ins[2])%65536
    elif op=='add': regs[ins[1]]=(regs[ins[1]]+val(ins[2]))%65536
    elif op=='mul': regs[ins[1]]=(regs[ins[1]]*val(ins[2]))%65536
    elif op=='mod':
        x=val(ins[2])
        if x>0: regs[ins[1]]%=x
    elif op=='dec': regs[ins[1]]=max(0,regs[ins[1]]-1)
    elif op=='jnz':
        x=val(ins[1]); k=val(ins[2])
        if x"'!=0: nxt=ip+k
    elif op=='"'skp':
        if val(ins[1])<val(ins[2]): nxt=ip+2
    elif op=='out': outs.append(val(ins[1])); total+=val(ins[1])
    ip=nxt
print('instructions',len(program),'steps',steps,'outputs',len(outs),'sum',total,'outs',outs,'regs',regs,'ip',ip)
Path('answer.txt').write_text(f'{total} {steps}\\n')
PY
cat answer.txt"

